package com.eventhub.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import org.springframework.format.annotation.DateTimeFormat;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "events")
public class Event {

    // Primary key identifier automatically generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Required title with character length constraints to prevent blank or excessive inputs
    @NotBlank(message = "Title is required")
    @Size(min = 3, max = 150, message = "Title must be between 3 and 150 characters")
    @Column(nullable = false, length = 150)
    private String title;

    // Category used for indexing and faceted search filtering (e.g., Workshop, Technical, Sports)
    @NotBlank(message = "Category is required")
    @Column(nullable = false, length = 50)
    private String category;

    // Extended description of event agenda and requirements
    @Column(columnDefinition = "TEXT")
    private String description;

    // Scheduled event date and time with standard ISO format parsing for HTML5 datetime-local inputs
    @NotNull(message = "Event date and time is required")
    @DateTimeFormat(pattern = "yyyy-MM-dd'T'HH:mm")
    @Column(name = "event_date", nullable = false)
    private LocalDateTime eventDate;

    // Physical venue address or virtual meeting room location
    @NotBlank(message = "Venue is required")
    @Column(nullable = false, length = 150)
    private String venue;

    // Maximum attendee limit allowed for this event
    @NotNull(message = "Capacity is required")
    @Min(value = 1, message = "Capacity must be at least 1")
    @Column(nullable = false)
    private Integer capacity;

    // Contact details of the organizer managing the event
    @NotBlank(message = "Organizer name is required")
    @Column(name = "organizer_name", nullable = false, length = 100)
    private String organizerName;

    // Email of organizer for automated notices and attendee inquiries
    @NotBlank(message = "Organizer email is required")
    @Email(message = "Valid email is required")
    @Column(name = "organizer_email", nullable = false, length = 100)
    private String organizerEmail;

    // Optional phone number of event coordinator
    @Column(name = "organizer_phone", length = 20)
    private String organizerPhone;

    // Promotional banner image web URL
    @Column(name = "banner_url", length = 255)
    private String bannerUrl;

    // Operational state of event: ACTIVE, CLOSED, or CANCELLED
    @Column(length = 20)
    private String status = "ACTIVE";

    // System audit timestamp recording when the event was created
    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt = LocalDateTime.now();

    // One-to-many relationship mapping all participant registrations for this event
    @OneToMany(mappedBy = "event", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.LAZY)
    private List<Registration> registrations = new ArrayList<>();

    public Event() {
    }

    public Event(String title, String category, String description, LocalDateTime eventDate, 
                 String venue, Integer capacity, String organizerName, String organizerEmail, 
                 String organizerPhone, String bannerUrl) {
        this.title = title;
        this.category = category;
        this.description = description;
        this.eventDate = eventDate;
        this.venue = venue;
        this.capacity = capacity;
        this.organizerName = organizerName;
        this.organizerEmail = organizerEmail;
        this.organizerPhone = organizerPhone;
        this.bannerUrl = bannerUrl;
        this.status = "ACTIVE";
        this.createdAt = LocalDateTime.now();
    }

    public int getRegisteredCount() {
        // Return total count of registered attendees associated with this event
        try {
            if (registrations != null && org.hibernate.Hibernate.isInitialized(registrations)) {
                return registrations.size();
            }
        } catch (Exception ignored) {
        }
        return 0;
    }

    public int getSeatsLeft() {
        // Protect against null capacity values
        if (capacity == null) return 0;
        // Subtract registered attendees from maximum capacity, bounded at 0
        return Math.max(0, capacity - getRegisteredCount());
    }

    public boolean isFull() {
        // Check if no seats remain available
        return getSeatsLeft() <= 0;
    }

    public boolean isUpcoming() {
        // Check if event start date is set in the future relative to system clock
        return eventDate != null && eventDate.isAfter(LocalDateTime.now());
    }

    public int getFillPercentage() {
        // Guard against zero division if capacity is empty
        if (capacity == null || capacity == 0) return 0;
        // Compute filled capacity percentage for visual progress bars
        int pct = (int) Math.round(((double) getRegisteredCount() / capacity) * 100);
        // Clamp percentage within valid [0, 100] bounds
        return Math.min(100, Math.max(0, pct));
    }

    public String getFormattedDate() {
        // Guard against null event date
        if (eventDate == null) return "N/A";
        // Format timestamp into human-readable display string
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("EEE, dd MMM yyyy, hh:mm a");
        return eventDate.format(formatter);
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public LocalDateTime getEventDate() {
        return eventDate;
    }

    public void setEventDate(LocalDateTime eventDate) {
        this.eventDate = eventDate;
    }

    public String getVenue() {
        return venue;
    }

    public void setVenue(String venue) {
        this.venue = venue;
    }

    public Integer getCapacity() {
        return capacity;
    }

    public void setCapacity(Integer capacity) {
        this.capacity = capacity;
    }

    public String getOrganizerName() {
        return organizerName;
    }

    public void setOrganizerName(String organizerName) {
        this.organizerName = organizerName;
    }

    public String getOrganizerEmail() {
        return organizerEmail;
    }

    public void setOrganizerEmail(String organizerEmail) {
        this.organizerEmail = organizerEmail;
    }

    public String getOrganizerPhone() {
        return organizerPhone;
    }

    public void setOrganizerPhone(String organizerPhone) {
        this.organizerPhone = organizerPhone;
    }

    public String getBannerUrl() {
        return bannerUrl;
    }

    public void setBannerUrl(String bannerUrl) {
        this.bannerUrl = bannerUrl;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public List<Registration> getRegistrations() {
        return registrations;
    }

    public void setRegistrations(List<Registration> registrations) {
        this.registrations = registrations;
    }
}
